                # start quoted field only if at beginning of a field
                if not field:
                    in_quotes = True
                else:
                    # stray quote inside unquoted field treated as literal
                    field.append(ch)
            elif ch == ',':
                fields.append(''.join(field))
                field = []
            else:
                field.append(ch)
        i += 1
    fields.append(''.join(field))
