def solve(tokens):
    stack = []
    for t in tokens:
        if t in ['+', '-', '*', '/']:
            b = stack.pop()
            a = stack.pop()
            if t == '+':
                stack.append(a + b)
            elif t == '-':
                stack.append(a - b)
            elif t == '*':
                stack.append(a * b)
            else:  # division truncates toward zero
                # Python's int division truncates toward negative infinity for //, need to mimic trunc toward zero
                # Use int(a / b) which truncates toward zero for both positive and negative.
                stack.append(int(a / b))
        else:
            stack.append(int(t))
    return stack[0]

