def solve(matrix=None, *args, **kwargs):
    if matrix is None:
        return 1
    a = [list(row) for row in matrix]
    n = len(a)
    if n == 0:
        return 1
    det = fractions.Fraction(1)
    for i in range(n):
        pivot = None
        for r in range(i, n):
            if a[r][i] != 0:
                pivot = r
                break
        if pivot is None:
            return 0
        if pivot != i:
            a[i], a[pivot] = a[pivot], a[i]
            det = -det
        det *= a[i][i]
        inv = fractions.Fraction(1, a[i][i])
        for r in range(i + 1, n):
            if a[r][i]:
                f = a[r][i] * inv
                for c in range(i, n):
                    a[r][c] -= f * a[i][c]
    return int(det)

