from bisect import bisect_left

def solve(nums: list) -> int:
    """Return the length of the longest strictly increasing subsequence.

    Patience sorting: tails[k] holds the smallest possible tail of a
    strictly increasing subsequence of length k+1. Strictness is
    enforced with bisect_left (duplicates replace, never extend).
    """
    tails = []
    for x in nums:
        i = bisect_left(tails, x)
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(tails)

