def solve(a, b):
    # Compute Levenshtein distance using DP O(len(a)*len(b))
    m, n = len(a), len(b)
    if m == 0:
        return n
    if n == 0:
        return m
    # previous row
    prev = list(range(n + 1))
    for i in range(1, m + 1):
        cur = [i] * (n + 1)
        cur[0] = i
        ai = a[i - 1]
        for j in range(1, n + 1):
            if ai == b[j - 1]:
                cost = 0
            else:
                cost = 1
            cur[j] = min(prev[j] + 1,        # deletion
                         cur[j - 1] + 1,    # insertion
                         prev[j - 1] + cost)  # substitution
        prev = cur
    return prev[n]

