def solve(coins: list, amount: int) -> int:
    """Return the fewest coins summing to amount, or -1 if impossible.

    Unbounded coin-change DP: dp[a] = min coins to make amount a.
    """
    INF = amount + 1
    dp = [0] + [INF] * amount
    for a in range(1, amount + 1):
        for c in coins:
            if c <= a and dp[a - c] + 1 < dp[a]:
                dp[a] = dp[a - c] + 1
