def solve(coins, amount):
    """Return the minimum number of coins needed to make up *amount*.
    *coins* is a list of positive integers (unlimited supply).
    If it is impossible, return -1.
    """
    # Edge case
    if amount == 0:
        return 0
    # Initialize DP array with a sentinel larger than any possible answer
    INF = amount + 1  # larger than max possible coins (using 1-value coin)
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for a in range(1, amount + 1):
        for c in coins:
            if c <= a:
                # If using coin c leads to a better solution, update
                if dp[a - c] + 1 < dp[a]:
                    dp[a] = dp[a - c] + 1
    return dp[amount] if dp[amount] != INF else -1

