def solve(n: int) -> int:
    """Return how many primes are strictly less than n.

    Sieve of Eratosthenes over [0, n).
    """
    if n <= 2:
        return 0
    sieve = bytearray([1]) * n  # sieve[i] == 1 means i is (possibly) prime
    sieve[0] = sieve[1] = 0
    i = 2
    while i * i < n:
